def transform(grid):
    import random

    h, w = len(grid), len(grid[0])
    out = [[0] * (2 * w) for _ in range(2 * h)]
    for r in range(h):
        for c in range(w):
            out[r][c] = grid[r][c]

    values = [v for row in grid for v in row]
    rng = random.Random(0)
    for r in range(2 * h):
        for c in range(2 * w):
            if r >= h or c >= w:
                out[r][c] = rng.choice(values)
    return out
