def transform(grid):
    n = len(grid)

    def rotate_cw(g):
        return [[g[n - 1 - c][r] for c in range(n)] for r in range(n)]

    def rotate_ccw(g):
        return [[g[c][n - 1 - r] for c in range(n)] for r in range(n)]

    cw = rotate_cw(grid)
    ccw = rotate_ccw(grid)
    half = [[grid[n - 1 - r][n - 1 - c] for c in range(n)] for r in range(n)]

    return [
        grid[r] + cw[r] for r in range(n)
    ] + [
        ccw[r] + half[r] for r in range(n)
    ]
